use std::error::Error;
use std::fs;

pub struct Config {
    pub query: String,
    pub file_path: String,
}

impl Config {
    pub fn build(args: &[String]) -> Result<Config, &'static str> {
        if args.len() < 3 {
            return Err("not enough arguments");
        }
        let query = args[1].clone();
        let file_path = args[2].clone();
        Ok(Config { query, file_path })
    }
}

pub fn run(config: Config) -> Result<(), Box<dyn Error>> {
    let contents = fs::read_to_string(config.file_path)?;
    println!("With text:\n{contents}");
    Ok(())
}

use std::env;
use std::process;

use minigrep::Config;

fn main() {
    let args: Vec<String> = env::args().collect();

    let config = Config::build(&args).unwrap_or_else(|err| {
        println!("Problem parsing arguments: {err}");
        process::exit(1);
    });

    println!("Searching for {}", config.query);
    println!("In file {}", config.file_path);

    if let Err(e) = minigrep::run(config) {
        println!("Application error: {e}");
        process::exit(1);
    }
}

struct Config {
    query: String,
    file_path: String,
    ignore_case: bool,
}

impl Config {
    fn build(args: &[String]) -> Result<Config, String> {
        if args.len() < 3 {
            return Err(String::from("not enough arguments"));
        }
        let query = args[1].clone();
        let file_path = args[2].clone();
        let ignore_case = false;
        Ok(Config { query, file_path, ignore_case })
    }
}

fn main() {
    let runs = [
        vec!["minigrep", "frog", "poem.txt"],
        vec!["minigrep", "frog", "poem.txt", "--ignore-case"],
        vec!["minigrep", "frog", "poem.txt", "-x"],
        vec!["minigrep", "frog", "poem.txt", "--ignore-case", "more"],
    ];
    for run in runs {
        let args: Vec<String> = run.iter().map(|s| s.to_string()).collect();
        match Config::build(&args) {
            Ok(c) => println!("{}/{}/{}", c.query, c.file_path, c.ignore_case),
            Err(e) => println!("error: {e}"),
        }
    }
}
